/* One-time migration from Chirpy's cache-first worker to ordinary HTTP. */
self.addEventListener('install', event => {
  event.waitUntil(self.skipWaiting());
});
self.addEventListener('activate', event => {
  event.waitUntil((async () => {
    const names = await caches.keys();
    await Promise.all(names.filter(name => name.startsWith('chirpy-')).map(name => caches.delete(name)));
    await self.clients.claim();
    const windows = await self.clients.matchAll({type:'window', includeUncontrolled:true});
    await self.registration.unregister();
    await Promise.all(windows.filter(client => {
      try { return new URL(client.url).origin === self.location.origin; } catch { return false; }
    }).map(client => client.navigate(client.url).catch(() => null)));
  })());
});
